/**
 * Live `<rel>Aggregate` selection suite (v2.7.0).
 *
 * Opt-in on NEO4J_URI. Labels are `ItAgg`-prefixed, every node carries this
 * run's `runId`, and `afterAll` deletes them.
 *
 * Through v2.6.x a `<rel>Aggregate` selection (generated by upstream
 * `@neo4j/graphql` 5.x, so present in migrated code) matched no field and
 * was silently dropped: `{ id postsAggregate { count } }` read `undefined`
 * (issue #23). It now compiles with upstream's shape and semantics, as pure
 * expressions valid at any depth on Neo4j 5.x, filtered by `where` and by
 * the target type's read policy.
 *
 * "Upstream" expectations come from two sources: hard-coded values worked
 * out from upstream's documented semantics, and an oracle that runs the
 * Cypher upstream 5.x generated for these fields (a `CALL` subquery per
 * aggregate, with `count` / `min` / `max` / `avg` / `sum`, and
 * `ORDER BY size(...) DESC` + `head` / `last` for strings), mapped through
 * upstream's output resolvers.
 */
import { randomUUID } from 'node:crypto';
import neo4j, { Driver, isInt } from 'neo4j-driver';
import { OGM } from '../../src/ogm';
import { permissive, restrictive } from '../../src/policy/types';

const URI = process.env.NEO4J_URI;
const describeLive = URI ? describe : describe.skip;
jest.setTimeout(60_000);

const typeDefs = /* GraphQL */ `
  interface ItAggContent {
    id: ID!
    runId: String
    title: String
    views: Int
    comments: [ItAggComment!]! @declareRelationship
  }
  type ItAggEdge @relationshipProperties {
    weight: Int
    score: Float
    big: BigInt
    at: DateTime
    note: String
    dur: Duration
  }
  union ItAggItem = ItAggPost | ItAggNote
  type ItAggUser @node {
    id: ID! @unique
    runId: String
    name: String
    posts: [ItAggPost!]!
      @relationship(
        type: "ITAGG_WROTE"
        direction: OUT
        properties: "ItAggEdge"
      )
    content: [ItAggContent!]! @relationship(type: "ITAGG_HAS", direction: OUT)
    others: [ItAggComment!]! @relationship(type: "ITAGG_HAS", direction: OUT)
    items: [ItAggItem!]!
      @relationship(type: "ITAGG_ITEM", direction: OUT, properties: "ItAggEdge")
    friends: [ItAggUser!]! @relationship(type: "ITAGG_FRIEND", direction: OUT)
  }
  type ItAggPost implements ItAggContent @node {
    id: ID! @unique
    runId: String
    title: String
    views: Int
    rating: Float
    big: BigInt
    xid: ID
    at: DateTime
    ldt: LocalDateTime
    lt: LocalTime
    t: Time
    dur: Duration
    d: Date
    flag: Boolean
    tags: [String!]
    hidden: Boolean
    author: ItAggUser
      @relationship(type: "ITAGG_WROTE", direction: IN, properties: "ItAggEdge")
    comments: [ItAggComment!]! @relationship(type: "ITAGG_ON", direction: IN)
  }
  type ItAggNote implements ItAggContent @node {
    id: ID! @unique
    runId: String
    title: String
    views: Int
    comments: [ItAggComment!]! @relationship(type: "ITAGG_ON", direction: IN)
  }
  type ItAggComment @node {
    id: ID! @unique
    runId: String
    text: String
    likes: Int
  }
`;

const policies = {
  ItAggPost: [
    permissive({ operations: ['*'], name: 'post.all', when: () => ({}) }),
    restrictive({
      operations: ['read'],
      name: 'post.visible',
      when: () => ({ hidden: false }),
    }),
  ],
  ItAggNote: [
    permissive({ operations: ['*'], name: 'note.all', when: () => ({}) }),
    restrictive({
      operations: ['read'],
      name: 'note.not-secret',
      when: () => ({ title_NOT: 'secret' }),
    }),
  ],
  ItAggComment: [
    permissive({ operations: ['*'], name: 'comment.all', when: () => ({}) }),
  ],
  ItAggUser: [
    permissive({ operations: ['*'], name: 'user.all', when: () => ({}) }),
  ],
};

type Row = Record<string, unknown>;

describeLive('<rel>Aggregate selections — live Neo4j (v2.7.0)', () => {
  const runId = `agg-${randomUUID()}`;
  const id = (s: string) => `${runId}-${s}`;
  let driver: Driver;
  let ogm: OGM;
  let strictOgm: OGM;
  let secured: OGM;

  async function run(cypher: string, params: Row = {}): Promise<Row[]> {
    const session = driver.session();
    try {
      const res = await session.run(cypher, { runId, ...params });
      return res.records.map((r) => r.toObject());
    } finally {
      await session.close();
    }
  }

  beforeAll(async () => {
    // Lossless integers: BigInt values above 2^53 must come back exact.
    driver = neo4j.driver(
      URI!,
      neo4j.auth.basic(
        process.env.NEO4J_USER ?? process.env.NEO4J_USERNAME ?? 'neo4j',
        process.env.NEO4J_PASSWORD ?? 'password',
      ),
    );
    await driver.verifyConnectivity();
    ogm = new OGM({ typeDefs, driver });
    strictOgm = new OGM({ typeDefs, driver, strict: true });
    secured = new OGM({ typeDefs, driver, policies });
    await run(
      `CREATE (u1:ItAggUser {id: $u1, runId: $runId, name: 'ann'})
       CREATE (u2:ItAggUser {id: $u2, runId: $runId, name: 'bob'})
       CREATE (u3:ItAggUser {id: $u3, runId: $runId, name: 'cat'})
       CREATE (u3)-[:ITAGG_FRIEND]->(u1), (u3)-[:ITAGG_FRIEND]->(u2)
       CREATE (p1:ItAggPost {id: $p1, runId: $runId, title: 'ab', views: 10, rating: 1.5,
         big: 9007199254740993, xid: 'b', at: datetime('2024-01-02T00:00:00Z'),
         ldt: localdatetime('2024-01-02T10:00:00'), lt: localtime('10:00'), t: time('10:00+02:00'),
         dur: duration('P1D'), d: date('2024-01-01'), flag: true, tags: ['x'], hidden: false})
       CREATE (p2:ItAggPost {id: $p2, runId: $runId, title: 'abcd', views: 20, rating: 2.5,
         big: 1, xid: 'a', at: datetime('2024-03-01T00:00:00Z'),
         ldt: localdatetime('2023-01-01T00:00:00'), lt: localtime('09:00'), t: time('09:00Z'),
         dur: duration('PT24H'), hidden: false})
       CREATE (p3:ItAggPost {id: $p3, runId: $runId, title: 'xyz', rating: 3.0, xid: 'c', hidden: false})
       CREATE (p4:ItAggPost {id: $p4, runId: $runId, title: 'zzzzzzzz', views: 1000, rating: 99.5,
         big: 100000, xid: '0', at: datetime('2030-01-01T00:00:00Z'),
         ldt: localdatetime('2030-01-01T00:00:00'), lt: localtime('23:00'), t: time('23:00Z'),
         dur: duration('P1Y'), hidden: true})
       CREATE (u1)-[:ITAGG_WROTE {weight: 1, score: 0.5, big: 5, at: datetime('2024-01-01T00:00:00Z'), note: 'x', dur: duration('PT1H')}]->(p1)
       CREATE (u1)-[:ITAGG_WROTE {weight: 3, score: 1.25, big: 7, note: 'yy', dur: duration('P2D')}]->(p2)
       CREATE (u1)-[:ITAGG_WROTE {score: 2.0, note: 'zzz'}]->(p3)
       CREATE (u1)-[:ITAGG_WROTE {weight: 100, score: 50.0, big: 100, at: datetime('2031-01-01T00:00:00Z'), note: 'hidden-note', dur: duration('P10Y')}]->(p4)
       CREATE (c1:ItAggComment {id: $c1, runId: $runId, text: 'c1', likes: 3})-[:ITAGG_ON]->(p1)
       CREATE (c2:ItAggComment {id: $c2, runId: $runId, text: 'c2', likes: 4})-[:ITAGG_ON]->(p1)
       CREATE (c3:ItAggComment {id: $c3, runId: $runId, text: 'c3', likes: 50})-[:ITAGG_ON]->(p4)
       CREATE (n1:ItAggNote {id: $n1, runId: $runId, title: 'note-1', views: 5})
       CREATE (:ItAggComment {id: $c4, runId: $runId, text: 'c4', likes: 9})-[:ITAGG_ON]->(n1)
       CREATE (n2:ItAggNote {id: $n2, runId: $runId, title: 'secret', views: 500})
       CREATE (cx:ItAggComment {id: $cx, runId: $runId, text: 'other', likes: 1})
       CREATE (u1)-[:ITAGG_HAS]->(p1), (u1)-[:ITAGG_HAS]->(p4), (u1)-[:ITAGG_HAS]->(n1),
              (u1)-[:ITAGG_HAS]->(n2), (u1)-[:ITAGG_HAS]->(cx)
       CREATE (u1)-[:ITAGG_ITEM {weight: 2}]->(p1), (u1)-[:ITAGG_ITEM {weight: 4}]->(n1),
              (u1)-[:ITAGG_ITEM {weight: 8}]->(p4)`,
      Object.fromEntries(
        [
          'u1',
          'u2',
          'u3',
          'p1',
          'p2',
          'p3',
          'p4',
          'c1',
          'c2',
          'c3',
          'c4',
          'n1',
          'n2',
          'cx',
        ].map((k) => [k, id(k)]),
      ),
    );
  });

  afterAll(async () => {
    if (!driver) return;
    await run('MATCH (n) WHERE n.runId = $runId DETACH DELETE n');
    await driver.close();
  });

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const model = (o: OGM, name: string): any => o.model(name);
  const user = async (
    o: OGM,
    u: string,
    selectionSet: string,
  ): Promise<Row> => {
    const rows = await model(o, 'ItAggUser').find({
      where: { id: id(u) },
      selectionSet,
    });
    expect(rows).toHaveLength(1);
    return rows[0];
  };
  const securedCtx = () => secured.withContext({}) as unknown as OGM;

  const FULL = `{ postsAggregate {
      count
      node {
        title { shortest longest }
        xid { shortest longest }
        views { min max average sum }
        rating { min max average sum }
        big { min max average sum }
        at { min max }
        ldt { min max }
        lt { min max }
        t { min max }
        dur { min max }
      }
      edge {
        weight { min max average sum }
        score { min max average sum }
        big { min max average sum }
        at { min max }
        note { shortest longest }
        dur { min max }
      }
    } }`;

  describe('every aggregate kind per scalar type', () => {
    it('matches upstream semantics (hard-coded expectations)', async () => {
      const row = await user(ogm, 'u1', FULL);
      expect(row.postsAggregate).toEqual({
        count: 4,
        node: {
          title: { shortest: 'ab', longest: 'zzzzzzzz' },
          // ID: shortest / longest are lexicographic min / max upstream.
          xid: { shortest: '0', longest: 'c' },
          // average: Neo4j avg() is an incremental mean, so its last bit
          // depends on match order (exactness: see the upstream oracle test).
          views: {
            min: 10,
            max: 1000,
            average: expect.closeTo(1030 / 3, 9),
            sum: 1030,
          },
          rating: {
            min: 1.5,
            max: 99.5,
            average: expect.closeTo(26.625, 9),
            sum: 106.5,
          },
          // BigInt: strings, as upstream's BigInt scalar serialized them —
          // exact past 2^53, and a float average in JavaScript's notation
          // (3002399751613664.5, not Cypher's 3.0023997516136645E15).
          big: {
            min: '1',
            max: '9007199254740993',
            average: expect.stringMatching(/^30023997516136\d\d(\.\d+)?$/),
            sum: '9007199254840994',
          },
          at: { min: '2024-01-02T00:00:00Z', max: '2030-01-01T00:00:00Z' },
          ldt: { min: '2023-01-01T00:00:00', max: '2030-01-01T00:00:00' },
          lt: { min: '09:00:00', max: '23:00:00' },
          t: { min: '10:00:00+02:00', max: '23:00:00Z' },
          dur: { min: 'P0M0DT86400S', max: 'P12M0DT0S' },
        },
        edge: {
          weight: {
            min: 1,
            max: 100,
            average: expect.closeTo(104 / 3, 9),
            sum: 104,
          },
          score: {
            min: 0.5,
            max: 50,
            average: expect.closeTo(13.4375, 9),
            sum: 53.75,
          },
          big: {
            min: '5',
            max: '100',
            average: expect.stringMatching(/^37\.3333333333333\d*$/),
            sum: '112',
          },
          at: { min: '2024-01-01T00:00:00Z', max: '2031-01-01T00:00:00Z' },
          note: { shortest: 'x', longest: 'hidden-note' },
          dur: { min: 'P0M0DT3600S', max: 'P120M0DT0S' },
        },
      });
    });

    it('empty set: count 0, sum 0, everything else null', async () => {
      const row = await user(ogm, 'u2', FULL);
      expect(row.postsAggregate).toEqual({
        count: 0,
        node: {
          title: { shortest: null, longest: null },
          xid: { shortest: null, longest: null },
          views: { min: null, max: null, average: null, sum: 0 },
          rating: { min: null, max: null, average: null, sum: 0 },
          big: { min: null, max: null, average: null, sum: '0' },
          at: { min: null, max: null },
          ldt: { min: null, max: null },
          lt: { min: null, max: null },
          t: { min: null, max: null },
          dur: { min: null, max: null },
        },
        edge: {
          weight: { min: null, max: null, average: null, sum: 0 },
          score: { min: null, max: null, average: null, sum: 0 },
          big: { min: null, max: null, average: null, sum: '0' },
          at: { min: null, max: null },
          note: { shortest: null, longest: null },
          dur: { min: null, max: null },
        },
      });
    });

    it('equals the Cypher upstream 5.x generated, through its resolvers', async () => {
      for (const u of ['u1', 'u2']) {
        const row = await user(ogm, u, FULL);
        expect(row.postsAggregate).toEqual(await upstreamPostsAggregate(u));
      }
    });

    it('also offers lexicographic min / max on ID and String', async () => {
      const row = await user(
        ogm,
        'u1',
        '{ postsAggregate { node { title { min max } xid { min max } } } }',
      );
      expect(row.postsAggregate).toEqual({
        node: {
          title: { min: 'ab', max: 'zzzzzzzz' },
          xid: { min: '0', max: 'c' },
        },
      });
    });

    it('aliases at every level, and __typename', async () => {
      const row = await user(
        ogm,
        'u1',
        `{ n: postsAggregate { __typename total: count node { __typename v: views { __typename top: max } } } }`,
      );
      expect(row.n).toEqual({
        __typename: 'ItAggUserItAggPostPostsAggregationSelection',
        total: 4,
        node: {
          __typename: 'ItAggUserItAggPostPostsNodeAggregateSelection',
          v: { __typename: 'IntAggregateSelection', top: 1000 },
        },
      });
    });
  });

  describe('arguments', () => {
    it('where filters the aggregated targets', async () => {
      const row = await user(
        ogm,
        'u1',
        '{ postsAggregate(where: { views_GT: 15 }) { count node { views { min sum } } edge { weight { sum } } } }',
      );
      expect(row.postsAggregate).toEqual({
        count: 2,
        node: { views: { min: 20, sum: 1020 } },
        edge: { weight: { sum: 103 } },
      });
    });

    it('directed: false matches both directions', async () => {
      const row = await user(
        ogm,
        'u1',
        '{ a: friendsAggregate { count } b: friendsAggregate(directed: false) { count } c: friendsAggregate(directed: true) { count } }',
      );
      expect(row).toEqual({
        a: { count: 0 },
        b: { count: 1 },
        c: { count: 0 },
      });
    });

    it('rejects options, unknown fields and unknown aggregates', async () => {
      await expect(
        user(ogm, 'u1', '{ postsAggregate(options: { limit: 1 }) { count } }'),
      ).rejects.toThrow(/options .* not supported on relationship aggregate/);
      await expect(
        user(ogm, 'u1', '{ postsAggregate { total } }'),
      ).rejects.toThrow(/Unknown field "total" on relationship aggregate/);
      await expect(
        user(ogm, 'u1', '{ postsAggregate { node { views { longest } } } }'),
      ).rejects.toThrow(/Unknown aggregate "longest"/);
      for (const f of ['flag', 'd', 'tags'])
        await expect(
          user(ogm, 'u1', `{ postsAggregate { node { ${f} { min } } } }`),
        ).rejects.toThrow(/has no aggregates/);
      // A list field: its generated member is a deprecated v2.6.3 leftover
      // (never aggregated); selecting it throws, in both APIs and modes.
      for (const o of [ogm, strictOgm]) {
        await expect(
          user(o, 'u1', '{ postsAggregate { node { tags { min } } } }'),
        ).rejects.toThrow(
          'Field "tags" ([String]) on postsAggregate.node has no aggregates: list fields are not aggregated.',
        );
        await expect(
          model(o, 'ItAggUser').find({
            select: {
              postsAggregate: {
                select: { node: { select: { tags: true } } },
              },
            },
          }),
        ).rejects.toThrow(
          'Field "tags" on postsAggregate.node has no aggregates: list fields are not aggregated.',
        );
      }
      await expect(
        user(ogm, 'u1', '{ friendsAggregate { edge { weight { sum } } } }'),
      ).rejects.toThrow(/no @relationshipProperties/);
      await expect(
        user(ogm, 'u1', '{ friends(directed: false) { id } }'),
      ).rejects.toThrow(/Unsupported argument "directed"/);
    });
  });

  describe('everywhere a selection is accepted', () => {
    it('nested depth 2 and 3', async () => {
      const row = await user(
        ogm,
        'u3',
        `{ friendsAggregate(directed: true) { count }
           friends { id postsAggregate { count node { views { max } } }
             posts { id commentsAggregate { count node { likes { sum max } } } } } }`,
      );
      expect(row.friendsAggregate).toEqual({ count: 2 });
      const friends = (row.friends as Row[]).sort((a, b) =>
        String(a.id).localeCompare(String(b.id)),
      );
      expect(friends[0].postsAggregate).toEqual({
        count: 4,
        node: { views: { max: 1000 } },
      });
      expect(friends[1].postsAggregate).toEqual({
        count: 0,
        node: { views: { max: null } },
      });
      const byPost = Object.fromEntries(
        (friends[0].posts as Row[]).map((p) => [p.id, p.commentsAggregate]),
      );
      expect(byPost).toEqual({
        [id('p1')]: { count: 2, node: { likes: { sum: 7, max: 4 } } },
        [id('p2')]: { count: 0, node: { likes: { sum: 0, max: null } } },
        [id('p3')]: { count: 0, node: { likes: { sum: 0, max: null } } },
        [id('p4')]: { count: 1, node: { likes: { sum: 50, max: 50 } } },
      });
    });

    it('connection node selection', async () => {
      const row = await user(
        ogm,
        'u1',
        '{ postsConnection(where: { node: { title: "ab" } }) { edges { node { id commentsAggregate { count } } } } }',
      );
      expect(row.postsConnection).toEqual({
        edges: [{ node: { id: id('p1'), commentsAggregate: { count: 2 } } }],
      });
    });

    it('interface target: node aggregates over the interface fields', async () => {
      const row = await user(
        ogm,
        'u1',
        '{ contentAggregate(where: { views_GT: 0 }) { count node { title { longest } views { sum } } } }',
      );
      // p1 (10), p4 (1000), n1 (5), n2 (500); cx has no views.
      expect(row.contentAggregate).toEqual({
        count: 4,
        node: { title: { longest: 'zzzzzzzz' }, views: { sum: 1515 } },
      });
    });

    it('union target: count and edge aggregates; node is rejected', async () => {
      const row = await user(
        ogm,
        'u1',
        '{ itemsAggregate { count edge { weight { sum max } } } }',
      );
      expect(row.itemsAggregate).toEqual({
        count: 3,
        edge: { weight: { sum: 14, max: 8 } },
      });
      await expect(
        user(ogm, 'u1', '{ itemsAggregate { node { id { min } } } }'),
      ).rejects.toThrow(/union ItAggItem, which has no node aggregates/);
    });

    it('fragments on a union and through InterfaceModel', async () => {
      const row = await user(
        ogm,
        'u1',
        `{ items { __typename ... on ItAggPost { id commentsAggregate { count } } } }`,
      );
      const posts = (row.items as Row[]).filter(
        (i) => i.__typename === 'ItAggPost',
      );
      expect(
        Object.fromEntries(posts.map((p) => [p.id, p.commentsAggregate])),
      ).toEqual({ [id('p1')]: { count: 2 }, [id('p4')]: { count: 1 } });
      for (const note of (row.items as Row[]).filter(
        (i) => i.__typename === 'ItAggNote',
      ))
        expect(note.commentsAggregate ?? null).toBeNull();

      const content = await ogm.interfaceModel('ItAggContent').find({
        where: { id_IN: [id('p1'), id('n1')] },
        selectionSet: `{ id ... on ItAggPost { commentsAggregate { count node { likes { sum } } } } }`,
      });
      const byId = Object.fromEntries(
        content.map((c: Row) => [c.id, c.commentsAggregate ?? null]),
      );
      expect(byId).toEqual({
        [id('p1')]: { count: 2, node: { likes: { sum: 7 } } },
        [id('n1')]: null,
      });
    });

    it('InterfaceModel: an interface-declared relationship, without a fragment', async () => {
      // Upstream generated no <rel>Aggregate on interface types; grafeo
      // compiles it against the declared relationship, as it does the list.
      const content = await ogm.interfaceModel('ItAggContent').find({
        where: { id_IN: [id('p1'), id('p2'), id('n1')] },
        selectionSet: `{ id commentsAggregate { count node { likes { max } } } comments { id } }`,
      });
      const byId = Object.fromEntries(
        content.map((c: Row) => [
          c.id,
          [c.commentsAggregate, (c.comments as Row[]).length],
        ]),
      );
      expect(byId).toEqual({
        [id('p1')]: [{ count: 2, node: { likes: { max: 4 } } }, 2],
        [id('p2')]: [{ count: 0, node: { likes: { max: null } } }, 0],
        [id('n1')]: [{ count: 1, node: { likes: { max: 9 } } }, 1],
      });
    });

    it('mutation response selectionSet', async () => {
      const res = await model(ogm, 'ItAggUser').update({
        where: { id: id('u1') },
        update: { name: 'ann' },
        selectionSet:
          '{ itAggUsers { id postsAggregate(where: { title: "ab" }) { count } } }',
      });
      expect(res.itAggUsers).toEqual([
        { id: id('u1'), postsAggregate: { count: 1 } },
      ]);
    });

    it('typed select', async () => {
      const [row] = await model(ogm, 'ItAggUser').find({
        where: { id: id('u1') },
        select: {
          id: true,
          postsAggregate: {
            where: { views_GT: 15 },
            select: {
              count: true,
              node: {
                select: {
                  views: { select: { sum: true, max: true } },
                  title: true,
                },
              },
              edge: { select: { weight: true } },
            },
          },
          friendsAggregate: { directed: false },
          itemsAggregate: true,
        },
      });
      expect(row).toEqual({
        id: id('u1'),
        postsAggregate: {
          count: 2,
          node: {
            views: { sum: 1020, max: 1000 },
            title: {
              shortest: 'abcd',
              longest: 'zzzzzzzz',
              min: 'abcd',
              max: 'zzzzzzzz',
            },
          },
          edge: {
            weight: { min: 3, max: 100, average: 51.5, sum: 103 },
          },
        },
        friendsAggregate: { count: 1 },
        itemsAggregate: {
          count: 3,
          edge: expect.objectContaining({
            weight: {
              min: 2,
              max: 8,
              average: expect.closeTo(14 / 3, 9),
              sum: 14,
            },
          }),
        },
      });
    });
  });

  describe('policies', () => {
    it('a policy-hidden node changes no aggregate (count / min / max / sum / average / edge)', async () => {
      const row = await user(securedCtx(), 'u1', FULL);
      // Readable: p1, p2, p3 (p4 is hidden).
      expect(row.postsAggregate).toMatchObject({
        count: 3,
        node: {
          title: { shortest: 'ab', longest: 'abcd' },
          xid: { shortest: 'a', longest: 'c' },
          views: { min: 10, max: 20, average: 15, sum: 30 },
          rating: { min: 1.5, max: 3, sum: 7 },
          big: { min: '1', max: '9007199254740993', sum: '9007199254740994' },
          at: { min: '2024-01-02T00:00:00Z', max: '2024-03-01T00:00:00Z' },
          dur: { min: 'P0M0DT86400S', max: 'P0M1DT0S' },
        },
        edge: {
          weight: { min: 1, max: 3, sum: 4, average: 2 },
          note: { shortest: 'x', longest: 'zzz' },
          dur: { min: 'P0M0DT3600S', max: 'P0M2DT0S' },
        },
      });
    });

    it('nested: hidden comments-target posts are not counted', async () => {
      const row = await user(
        securedCtx(),
        'u3',
        '{ friends { id postsAggregate { count node { views { max } } } } }',
      );
      const ann = (row.friends as Row[]).find((f) => f.id === id('u1'))!;
      expect(ann.postsAggregate).toEqual({
        count: 3,
        node: { views: { max: 20 } },
      });
    });

    it('abstract targets: each member’s own read policy', async () => {
      const row = await user(
        securedCtx(),
        'u1',
        `{ contentAggregate { count node { views { max sum } title { longest } } }
           content { id }
           itemsAggregate { count edge { weight { sum max } } } items { __typename } }`,
      );
      // content: p1, n1 readable; p4 (hidden post) and n2 (secret note) are
      // not, and the per-member policy clause also requires a member label,
      // so cx (a comment on the shared ITAGG_HAS type) is out — as in the list.
      expect(row.content as Row[]).toHaveLength(2);
      expect(row.contentAggregate).toEqual({
        count: 2,
        node: { views: { max: 10, sum: 15 }, title: { longest: 'note-1' } },
      });
      expect(row.itemsAggregate).toEqual({
        count: 2,
        edge: { weight: { sum: 6, max: 4 } },
      });
      expect(row.items as Row[]).toHaveLength(2);
    });

    it('strict mode: an abstract target counts its members only (v2.6.2 F8)', async () => {
      const plain = await user(
        ogm,
        'u1',
        '{ contentAggregate { count } content { id } }',
      );
      const strict = await user(
        strictOgm,
        'u1',
        '{ contentAggregate { count } content { id } }',
      );
      expect(plain.contentAggregate).toEqual({ count: 5 });
      expect(plain.content as Row[]).toHaveLength(5);
      expect(strict.contentAggregate).toEqual({ count: 4 });
      expect(strict.content as Row[]).toHaveLength(4);
    });

    it('typed select under a policy context', async () => {
      const [row] = await model(securedCtx(), 'ItAggUser').find({
        where: { id: id('u1') },
        select: {
          postsAggregate: {
            select: {
              count: true,
              node: { select: { views: { select: { max: true } } } },
            },
          },
        },
      });
      expect(row.postsAggregate).toEqual({
        count: 3,
        node: { views: { max: 20 } },
      });
    });
  });

  /**
   * The Cypher upstream 5.x generated for `postsAggregate` with FULL's
   * selection (`AggregationOperation` + `AggregationAttributeField` /
   * `CountField`): one `CALL` per field with the aggregating functions;
   * strings `ORDER BY size DESC` then `head` / `last`; ID `min` / `max`.
   * Mapped through upstream's resolvers: `numericalResolver` (Integer →
   * number), the `BigInt` scalar (→ string). Temporals use grafeo's ISO
   * string mapping (upstream's DateTime went through APOC; see README).
   */
  async function upstreamPostsAggregate(u: string): Promise<Row> {
    const m = (target: string, body: string) =>
      `CALL { WITH this MATCH (this)-[r:ITAGG_WROTE]->(t:ItAggPost) ${body.replace(/\$v/g, target)} }`;
    const num = (v: string, alias: string) =>
      m(
        v,
        `RETURN { min: min($v), max: max($v), average: avg($v), sum: sum($v) } AS ${alias}`,
      );
    const mm = (v: string, alias: string) =>
      m(v, `RETURN { min: min($v), max: max($v) } AS ${alias}`);
    const str = (v: string, alias: string) =>
      m(
        v,
        `WITH t, r ORDER BY size($v) DESC WITH collect($v) AS list RETURN { longest: head(list), shortest: last(list) } AS ${alias}`,
      );
    const [rec] = await run(
      `MATCH (this:ItAggUser {id: $id})
       ${m('t', 'RETURN count(t) AS count')}
       ${str('t.title', 'title')}
       ${m('t.xid', 'RETURN { shortest: min($v), longest: max($v) } AS xid')}
       ${num('t.views', 'views')} ${num('t.rating', 'rating')} ${num('t.big', 'big')}
       ${mm('t.at', 'at')} ${mm('t.ldt', 'ldt')} ${mm('t.lt', 'lt')} ${mm('t.t', 't')} ${mm('t.dur', 'dur')}
       ${num('r.weight', 'eweight')} ${num('r.score', 'escore')} ${num('r.big', 'ebig')}
       ${mm('r.at', 'eat')} ${str('r.note', 'enote')} ${mm('r.dur', 'edur')}
       RETURN *`,
      { id: id(u) },
    );
    const numeric = (v: unknown) => (isInt(v) ? v.toNumber() : v);
    const bigint = (v: unknown) =>
      v === null ? null : isInt(v) ? v.toString() : (v as number).toString(10);
    const temporal = (v: unknown) => (v === null ? null : String(v));
    const map = (o: unknown, f: (v: unknown) => unknown) =>
      Object.fromEntries(Object.entries(o as Row).map(([k, v]) => [k, f(v)]));
    return {
      count: numeric(rec.count),
      node: {
        title: rec.title,
        xid: rec.xid,
        views: map(rec.views, numeric),
        rating: map(rec.rating, numeric),
        big: map(rec.big, bigint),
        at: map(rec.at, temporal),
        ldt: map(rec.ldt, temporal),
        lt: map(rec.lt, temporal),
        t: map(rec.t, temporal),
        dur: map(rec.dur, temporal),
      },
      edge: {
        weight: map(rec.eweight, numeric),
        score: map(rec.escore, numeric),
        big: map(rec.ebig, bigint),
        at: map(rec.eat, temporal),
        note: rec.enote,
        dur: map(rec.edur, temporal),
      },
    };
  }
});
